1	import { existsSync, statSync } from "node:fs";
2	import { homedir } from "node:os";
3	import { isAbsolute, join, resolve, sep } from "node:path";
4	import { KIMI_LANES, kimiLaneEnv, kimiPreferenceForAgentId } from "./kimi.js";
5	
6	// ───────────────────────────────────────────────────────────────────────────
7	// Kimi-native dispatch: AgentSwarm (waves) + /goal (the run loop)
8	//
9	// The harness-native counterpart to wave-dispatch.js's Codex spawn_agent lane.
10	// Where Codex offers only per-agent spawn (muster supplies the fan-out, the
11	// barrier, and the aggregation), Kimi ships BOTH halves natively:
12	//
13	//   AgentSwarm  -> fan-out + barrier + aggregated report, in ONE tool call
14	//   /goal       -> the continue-until-done loop, with machine-readable
15	//                  terminal states delivered as process exit codes
16	//
17	// so muster keeps the judgment (what the waves ARE, what the objective SAYS)
18	// and hands the mechanics to the harness -- the harness-native-first posture.
19	//
20	// EVIDENCE NOTE. The constants below are read from the shipped kimi binary's
21	// own tool schema (`~/.kimi-code/bin/kimi`, v0.29.0, unstripped), not inferred
22	// from prose. That matters because the published docs state the placeholder
23	// exists without ever naming it, and omit the distinct-prompts rule entirely.
24	// Where the binary and the docs disagree, the binary is what actually runs.
25	// ───────────────────────────────────────────────────────────────────────────
26	
27	// --- AgentSwarm -------------------------------------------------------------
28	
29	// Verbatim from the binary: `PROMPT_TEMPLATE_PLACEHOLDER = "{{item}}"`, and the
30	// tool description's own words -- "The placeholder is exactly `{{item}}`."
31	export const KIMI_SWARM_PLACEHOLDER = "{{item}}";
32	export const KIMI_SWARM_MAX_SUBAGENTS = 128;
33	export const KIMI_SWARM_MIN_ITEMS = 2;
34	
35	// The swarm's model lane. Kimi accepts only the symbolic pair -- never a model
36	// id (src/kimi.js's KIMI_LANES explains the tier->lane fold).
37	const LANES = Object.keys(KIMI_LANES);
38	
39	// Kimi rejects a malformed swarm BEFORE any subagent starts ("a violation is
40	// rejected before any subagent starts"), so a bad packet costs a whole wave's
41	// round trip. muster validates the same four rules up front and fails loud with
42	// the offending detail, rather than discovering them from a rejection:
43	//   1. items >= 2 unless resume_agent_ids is present
44	//   2. prompt_template is required whenever items are present
45	//   3. prompt_template must contain {{item}}
46	//   4. the FILLED prompts must be distinct -- "two items that expand to the
47	//      same prompt are rejected". This rule appears nowhere in the published
48	//      docs; it is enforced in the binary. Duplicate wave items are exactly
49	//      how muster would trip it (e.g. two crew members handed the same file).
50	export function kimiSwarmCall({ promptTemplate, items = [], subagentType, model, resumeAgentIds } = {}) {
51	  // resume_agent_ids maps a PRIOR subagent's agent id to the prompt used to
52	  // resume it -- the orchestrator's re-dispatch-once failure rule rides this:
53	  // a failed swarm member is resumed with only the error context appended,
54	  // keeping its prior context instead of paying a fresh full prompt again.
55	  if (resumeAgentIds !== undefined) {
56	    if (typeof resumeAgentIds !== "object" || resumeAgentIds === null || Array.isArray(resumeAgentIds)) {
57	      throw new Error("kimiSwarmCall: resumeAgentIds must be a map of prior agent id -> resume prompt");
58	    }
59	    for (const [id, prompt] of Object.entries(resumeAgentIds)) {
60	      if (!id) throw new Error("kimiSwarmCall: resumeAgentIds keys must be prior agent ids (non-empty strings)");
61	      if (typeof prompt !== "string" || !prompt) {
62	        throw new Error(`kimiSwarmCall: resumeAgentIds[${JSON.stringify(id)}] must be the resume prompt (the appended error context), a non-empty string`);
63	      }
64	    }
65	  }
66	  const resume = resumeAgentIds && Object.keys(resumeAgentIds).length ? resumeAgentIds : null;
67	  if (!Array.isArray(items)) throw new Error("kimiSwarmCall: items must be an array");
68	  if (!items.length && !resume) throw new Error("kimiSwarmCall: pass items or resumeAgentIds");
69	  if (items.length && !resume && items.length < KIMI_SWARM_MIN_ITEMS) {
70	    throw new Error(`kimiSwarmCall: AgentSwarm requires at least ${KIMI_SWARM_MIN_ITEMS} items (got ${items.length}); use a single Agent call instead`);
71	  }
72	  if (items.length > KIMI_SWARM_MAX_SUBAGENTS) {
73	    throw new Error(`kimiSwarmCall: AgentSwarm supports at most ${KIMI_SWARM_MAX_SUBAGENTS} subagents (got ${items.length})`);
74	  }
75	  if (items.length && typeof promptTemplate !== "string") {
76	    throw new Error("kimiSwarmCall: prompt_template is required when items are provided");
77	  }
78	  if (typeof promptTemplate === "string" && !promptTemplate.includes(KIMI_SWARM_PLACEHOLDER)) {
79	    throw new Error(`kimiSwarmCall: prompt_template must contain the ${KIMI_SWARM_PLACEHOLDER} placeholder`);
80	  }
81	  if (model !== undefined && !LANES.includes(model)) {
82	    throw new Error(`kimiSwarmCall: model must be one of ${LANES.join("|")} (Kimi takes a lane, never a model id); got ${JSON.stringify(model)}`);
83	  }
84	  if (items.length) {
85	    const filled = items.map(item => promptTemplate.split(KIMI_SWARM_PLACEHOLDER).join(item));
86	    const seen = new Set();
87	    for (const [index, prompt] of filled.entries()) {
88	      if (seen.has(prompt)) {
89	        throw new Error(`kimiSwarmCall: items must expand to DISTINCT prompts -- item ${index} (${JSON.stringify(items[index])}) repeats an earlier prompt; Kimi rejects the whole swarm`);
90	      }
91	      seen.add(prompt);
92	    }
93	  }
94	  return {
95	    tool: "AgentSwarm",
96	    ...(promptTemplate !== undefined ? { prompt_template: promptTemplate } : {}),
97	    ...(items.length ? { items: [...items] } : {}),
98	    ...(resume ? { resume_agent_ids: { ...resume } } : {}),
99	    ...(subagentType ? { subagent_type: subagentType } : {}),
100	    ...(model ? { model } : {}),
101	    // Not a field -- a caller contract. The binary enforces it: "If AgentSwarm
102	    // is called, that call must be the only tool call in the response."
103	    soleToolCall: true
104	  };
105	}
106	
107	// One wave task as a single Agent call -- the right shape when a wave's crew
108	// members are differently-shaped ("For a few differently-shaped tasks, make
109	// separate `Agent` calls in one message instead"), which is muster's usual
110	// case: a wave is typically N DISTINCT roles, not one task over N inputs.
111	// `agentId` is the crew member's resolved chosen.id; its lane is derived from
112	// the shared manifest so a dispatch can never contradict the installed
113	// agent file's stamped model_preference.
114	//
115	// `resume` is the failure-retry path (orchestrator step 4a's re-dispatch-once
116	// rule on Kimi): Kimi's `resume` takes the FAILED subagent's agent id and is
117	// mutually exclusive with `subagent_type`, and a resumed subagent keeps its
118	// prior context AND its model (an explicit `model` is "ignored when
119	// resuming") -- so the retry packet carries neither, only the error context
120	// as the new prompt. That is the whole point: the retry never pays the full
121	// prompt/context cost a fresh spawn would.
122	export function kimiAgentCall({ agentId, prompt, description, background = false, model, resume } = {}) {
123	  if (resume !== undefined && (typeof resume !== "string" || !resume)) {
124	    throw new Error("kimiAgentCall: resume must be the failed subagent's agent id (a non-empty string)");
125	  }
126	  if (resume && agentId) {
127	    throw new Error("kimiAgentCall: resume is mutually exclusive with agentId -- Kimi pairs resume with no subagent_type; the resumed subagent keeps its own type");
128	  }
129	  if (!resume && (typeof agentId !== "string" || !agentId)) throw new Error("kimiAgentCall: agentId is required (the crew member's resolved chosen.id)");
130	  if (typeof prompt !== "string" || !prompt) throw new Error(`kimiAgentCall: prompt is required for agent "${agentId || resume}"`);
131	  if (model !== undefined && !LANES.includes(model)) {
132	    throw new Error(`kimiAgentCall: model must be one of ${LANES.join("|")}; got ${JSON.stringify(model)}`);
133	  }
134	  if (resume) {
135	    return {
136	      tool: "Agent",
137	      resume,
138	      prompt,
139	      description: description || `retry ${resume}`,
140	      ...(background ? { run_in_background: true } : {})
141	    };
142	  }
143	  // An explicit tool-call model wins over the profile's model_preference; when
144	  // the caller does not force one, derive the agent's own lane so the dispatch
145	  // agrees with what `muster install kimi` stamped into its frontmatter.
146	  const lane = model ?? kimiPreferenceForAgentId(agentId) ?? undefined;
147	  return {
148	    tool: "Agent",
149	    subagent_type: agentId,
150	    prompt,
151	    description: description || agentId,
152	    ...(background ? { run_in_background: true } : {}),
153	    ...(lane ? { model: lane } : {})
154	  };
155	}
156	
157	// --- Background legs (run_in_background) -------------------------------------
158	
159	// `background: true` maps to Kimi's `run_in_background`: the dispatch returns a
160	// TASK ID immediately (the parent does NOT wait) and the result arrives in a
161	// LATER turn as a synthetic user message, with the on-disk receipt at the
162	// session's tasks/<task_id>.json + tasks/<task_id>/output.log
163	// (docs/research/kimi-code-cli.md secs 6+8). muster never polls a backgrounded
164	// leg -- the completion arrives on its own -- so the fold-back is a pure
165	// function of the completion receipt:
166	//   completed -> the synthetic message's body IS the subagent's final message
167	//     (the whole handoff, same return contract as a foreground leg); fold it
168	//     back verbatim.
169	//   failed (any terminal state that is not completed) -> the leg re-enters
170	//     orchestrator step 4a's re-dispatch-once rule (a resume retry on Kimi) --
171	//     a backgrounded leg is never a silent drop.
172	//   anything else -> still in flight: pending. The wave's barrier does NOT
173	//     cover a pending leg -- which is exactly why barrier-gated work never
174	//     dispatches background (orchestrator/SKILL.md's Kimi-native dispatch
175	//     subsection).
176	export function interpretKimiBackgroundCompletion({ status, result, terminalReason } = {}) {
177	  if (status === "completed") {
178	    return {
179	      status: "complete",
180	      terminal: true,
181	      result,
182	      reason: "completion receipt arrived as a synthetic user message -- the body is the subagent's final message, the whole handoff"
183	    };
184	  }
185	  if (status === "failed" || status === "stopped" || status === "timed_out") {
186	    return {
187	      status: "failed",
188	      terminal: true,
189	      reason: `background leg ended ${status}${terminalReason ? ` (${terminalReason})` : ""} -- re-enters the re-dispatch-once rule (a resume retry), never a silent drop`
190	    };
191	  }
192	  return { status: "pending", terminal: false, reason: "no completion receipt yet -- the leg is still in flight and the wave's barrier does not cover it" };
193	}
194	
195	// --- /goal: the run loop ----------------------------------------------------
196	
197	// Verbatim from the binary: `GOAL_EXIT_CODES = { complete: 0, blocked: 3,
198	// paused: 6 }` and `MAX_GOAL_OBJECTIVE_LENGTH = 4000`.
199	export const KIMI_GOAL_EXIT_CODES = Object.freeze({ complete: 0, blocked: 3, paused: 6 });
200	export const KIMI_GOAL_MAX_OBJECTIVE = 4000;
201	
202	// Briefs ride argv as the `-p` prompt -- the same budget class as a /goal
203	// objective (which is itself a `-p "/goal <objective>"` argument). No separate
204	// binary limit is documented for a bare -p prompt, so the objective cap is
205	// adopted as the conservative bound.
206	export const KIMI_PROCESS_MAX_BRIEF = KIMI_GOAL_MAX_OBJECTIVE;
207	
208	// Map a `kimi -p "/goal ..."` process exit code onto muster's run disposition.
209	// This is the whole reason /goal is worth adopting: muster's escalation signal
210	// arrives as an exit code instead of being parsed out of a STATE file.
211	//   complete -> the objective's own evidence was satisfied; finish/disposition
212	//   blocked  -> needs input, cannot proceed as stated, or hit a budget limit
213	//               == muster's ESCALATION, and the goal writes its own reason
214	//   paused   -> interrupted / resumed / model-or-runtime error; resumable
215	// Any other code is a harness fault, not a goal outcome -- never silently
216	// treated as an escalation (that would report a crash as a clean stop).
217	export function interpretKimiGoalExit(code) {
218	  const status = Object.keys(KIMI_GOAL_EXIT_CODES).find(name => KIMI_GOAL_EXIT_CODES[name] === code);
219	  if (!status) return { status: "failed", terminal: true, escalate: true, reason: `kimi exited ${code} -- not a /goal terminal state` };
220	  return {
221	    status,
222	    terminal: status === "complete",
223	    escalate: status === "blocked",
224	    resumable: status === "paused",
225	    reason: { complete: "goal satisfied", blocked: "goal blocked -- needs input or hit a limit", paused: "goal paused -- resumable" }[status]
226	  };
227	}
228	
229	// Build the argv + env for an unattended `kimi -p "/goal <objective>"` run.
230	//
231	// Why the objective carries the acceptance criteria rather than a checklist
232	// file: "/goal does not have a separate stop-limit flag. Write stop conditions
233	// into the objective", and goals "work best when the objective names the finish
234	// line and the evidence that proves it". So muster's assessed acceptance
235	// criteria compile straight INTO the objective string -- the same enrichment,
236	// spent on the harness's own loop instead of on a file muster re-reads.
237	//
238	// The env pair is what binds the model lanes (src/kimi-install.js): per-process,
239	// so nothing in the user's shared config.toml is touched. It comes from
240	// kimiLaneEnv() -- the single derivation in src/kimi.js -- so this run loop,
241	// the install report, and `muster doctor` can never disagree on the bind.
242	// Note the flag is also what selects the v2 engine under `kimi -p`, which is
243	// what makes model_preference bite at all.
244	export function kimiGoalInvocation({ objective, primaryModel = KIMI_LANES.primary, secondaryModel = KIMI_LANES.secondary, streamJson = false } = {}) {
245	  if (typeof objective !== "string" || !objective.trim()) throw new Error("kimiGoalInvocation: objective is required");
246	  if (objective.length > KIMI_GOAL_MAX_OBJECTIVE) {
247	    throw new Error(`kimiGoalInvocation: objective is ${objective.length} chars; Kimi caps it at ${KIMI_GOAL_MAX_OBJECTIVE}`);
248	  }
249	  if (/^\/goal(\s|$)/.test(objective)) throw new Error("kimiGoalInvocation: pass the bare objective; the /goal prefix is added here");
250	  return {
251	    argv: ["-p", `/goal ${objective}`, ...(streamJson ? ["--output-format", "stream-json"] : []), "-m", primaryModel],
252	    env: {
253	      // Selects the v2 engine AND enables the secondary-model experiment; the
254	      // lane model follows the (rarely overridden) secondaryModel argument.
255	      // An OVERRIDE pair: merge over the ambient env at spawn
256	      // (`{ ...process.env, ...env }`), never pass as the whole env.
257	      ...kimiLaneEnv(),
258	      KIMI_SECONDARY_MODEL: secondaryModel
259	    },
260	    exitCodes: KIMI_GOAL_EXIT_CODES
261	  };
262	}
263	
264	// --- Headless process dispatch (`kimi -p --agent-file`) ----------------------
265	
266	// Where `muster install kimi` places the stamped agent files
267	// (src/kimi-install.js): $KIMI_CODE_HOME/agents, else ~/.kimi-code/agents.
268	// Resolved per call so a relocated Kimi home (and tests) are honored.
269	const kimiAgentsDir = () => join(process.env.KIMI_CODE_HOME || join(homedir(), ".kimi-code"), "agents");
270	
271	// Build the argv + env for a headless `kimi -p <brief> --agent-file <path>`
272	// process -- a wave leg dispatched as its OWN Kimi process rather than as an
273	// in-session Agent/AgentSwarm call. `--agent-file` binds a custom MAIN agent
274	// (docs/research/kimi-code-cli.md section 9, "How muster would actually drive
275	// Kimi non-interactively"), which requires the v2 engine. The kimiLaneEnv()
276	// pair rides for BOTH of its keys, not the flag alone: KIMI_CODE_EXPERIMENTAL_FLAG=1
277	// selects the engine --agent-file needs, and KIMI_SECONDARY_MODEL binds the
278	// lanes for any subagents the dispatched -p process itself spawns -- which is
279	// exactly where the stamped model_preference bites. It never binds the -p
280	// process's own MAIN agent (sections 6 + 11.8) -- so the process's model comes
281	// ONLY from `-m`.
282	//
283	// LANE IS THEREFORE REQUIRED AND ALWAYS EMITTED as `-m KIMI_LANES[lane]`.
284	// Omitting -m is not neutral: the process would silently fall to config.toml's
285	// default_model (k3), demoting an execution-lane leg onto the judgment model
286	// (and its quota) with no signal. There is no construction path without -m.
287	export function kimiProcessDispatch({ brief, agentFile, cwd, lane } = {}) {
288	  if (typeof brief !== "string" || !brief.trim()) {
289	    throw new Error("kimiProcessDispatch: brief is required (the -p prompt the dispatched process runs)");
290	  }
291	  if (brief.length > KIMI_PROCESS_MAX_BRIEF) {
292	    throw new Error(`kimiProcessDispatch: brief is ${brief.length} chars; cap is ${KIMI_PROCESS_MAX_BRIEF} -- briefs ride argv as the -p prompt, the same budget class as a /goal objective`);
293	  }
294	  if (!LANES.includes(lane)) {
295	    throw new Error(`kimiProcessDispatch: lane is required and must be one of ${LANES.join("|")} -- model_preference never binds the -p process's own main agent, so its model comes ONLY from -m; omitting it silently falls to config default_model; got ${JSON.stringify(lane)}`);
296	  }
297	  if (typeof cwd !== "string" || !cwd) {
298	    throw new Error("kimiProcessDispatch: cwd is required (the directory the process runs in)");
299	  }
300	  const resolvedCwd = resolve(cwd);
301	  if (!existsSync(resolvedCwd) || !statSync(resolvedCwd).isDirectory()) {
302	    throw new Error(`kimiProcessDispatch: cwd must be an existing directory; got ${JSON.stringify(cwd)}`);
303	  }
304	  if (typeof agentFile !== "string" || !agentFile) {
305	    throw new Error("kimiProcessDispatch: agentFile is required (a name under the installed agents dir, or an explicit path)");
306	  }
307	  // A bare name resolves under the installed agents dir; anything carrying a
308	  // path separator is an explicit path (absolute as-is, or relative to the
309	  // run's cwd). Either way the file must exist -- discovered here, not from a
310	  // failed spawn.
311	  const resolvedAgentFile = isAbsolute(agentFile)
312	    ? agentFile
313	    : agentFile.includes("/") || agentFile.includes(sep)
314	      ? resolve(resolvedCwd, agentFile)
315	      : join(kimiAgentsDir(), agentFile);
316	  if (!existsSync(resolvedAgentFile) || !statSync(resolvedAgentFile).isFile()) {
317	    throw new Error(`kimiProcessDispatch: agentFile ${JSON.stringify(agentFile)} resolved to ${resolvedAgentFile}, which does not exist (bare names resolve under the installed agents dir ${kimiAgentsDir()}; explicit paths resolve against cwd)`);
318	  }
319	  return {
320	    argv: ["-p", brief, "--agent-file", resolvedAgentFile, "--output-format", "stream-json", "-m", KIMI_LANES[lane]],
321	    // An OVERRIDE pair: merge over the ambient env at spawn
322	    // (`{ ...process.env, ...d.env }`), never pass as the whole env -- a
323	    // wholesale replacement loses HOME/PATH and the child breaks.
324	    env: kimiLaneEnv(),
325	    cwd: resolvedCwd,
326	    lane
327	  };
328	}
329	
330	// --- Wave dispatch mode selection -------------------------------------------
331	
332	export const KIMI_DISPATCH_MODES = Object.freeze({
333	  SWARM: "agent-swarm",
334	  AGENT_CALLS: "agent-calls"
335	});
336	
337	// Pick the native shape for a wave, mirroring resolveCodexWaveDispatch's
338	// declared-not-probed posture. The choice is structural, straight from the
339	// binary's own guidance: AgentSwarm is for "the same kind of task over
340	// different inputs"; "For a few differently-shaped tasks, make separate `Agent`
341	// calls in one message instead."
342	//
343	// muster waves are usually the SECOND shape -- a wave is N distinct roles
344	// (builder + test-author + reviewer), not one template over N inputs -- so
345	// agent-calls is the default and swarm is selected only for a genuinely
346	// uniform fan-out (audit N files, review N modules), which is also the only
347	// shape that can satisfy the distinct-prompts rule cleanly.
348	export function resolveKimiWaveDispatch({ items = [], uniformTask = false } = {}) {
349	  if (uniformTask && items.length >= KIMI_SWARM_MIN_ITEMS) {
350	    return {
351	      mode: KIMI_DISPATCH_MODES.SWARM,
352	      reason: `uniform task over ${items.length} inputs -- one AgentSwarm call fans out, barriers, and returns an aggregated report (must be the sole tool call in its response)`,
353	      concurrencyEnv: "KIMI_CODE_AGENT_SWARM_MAX_CONCURRENCY"
354	    };
355	  }
356	  return {
357	    mode: KIMI_DISPATCH_MODES.AGENT_CALLS,
358	    reason: items.length < KIMI_SWARM_MIN_ITEMS
359	      ? `only ${items.length} item(s) -- below AgentSwarm's ${KIMI_SWARM_MIN_ITEMS}-item floor; dispatch as Agent calls`
360	      : "differently-shaped crew roles -- separate Agent calls in one message, per Kimi's own guidance; AgentSwarm is for one task over many inputs"
361	  };
362	}

1	#!/usr/bin/env node
2	// Reviewer-tier experiment harness (rerunnable): does the execution lane
3	// (kimi-code/kimi-for-coding) review as well as the judgment lane
4	// (kimi-code/k3)? Two pinned probes x two lanes, each cell one headless
5	// `kimi -p --agent-file` process via kimiProcessDispatch (src/kimi-dispatch.js).
6	//
7	//   PROBE 1 (review-gate pass): the diff of commit 9027136 (parent of the
8	//     env-merge fix 3cf6084), reviewed with a review-gate-style brief. The
9	//     KNOWN-BLOCKER list is pinned verbatim below as the human-judgment rubric.
10	//   PROBE 2 (spec-gate pass): a small synthetic Crew Manifest (pinned below)
11	//     whose outcome claims the stamped model_preference on a --agent-file agent
12	//     engages the -p process's own model lanes. Expected: FAIL naming the
13	//     misattribution (model_preference binds only SPAWNED SUBAGENTS; the -p
14	//     main agent's model comes ONLY from -m).
15	//
16	// RUBRIC: caught/missed is HUMAN JUDGMENT applied later by the orchestrator.
17	// This harness does NOT keyword-score; it records each run's raw verdict text
18	// verbatim into the results JSON for that step.
19	//
20	// Modes:
21	//   node eval/kimi-reviewer-tier-probe.mjs --dry-run   build all descriptors and
22	//                                                      print them as JSON; spawn NOTHING
23	//   node eval/kimi-reviewer-tier-probe.mjs [--out <path>] [--results-dir <dir>]
24	//                                                      live mode: spawn every cell
25	//                                                      (wave 2 runs this)
26	import { execFileSync, execFile } from "node:child_process";
27	import { promisify } from "node:util";
28	import { mkdir, writeFile } from "node:fs/promises";
29	import { fileURLToPath } from "node:url";
30	import { dirname, join, resolve } from "node:path";
31	import { kimiProcessDispatch, KIMI_PROCESS_MAX_BRIEF } from "../src/kimi-dispatch.js";
32	import { captureSessionId, resolveSessionForCwd, readSessionUsage } from "../src/kimi-receipts.js";
33	
34	const pexecFile = promisify(execFile);
35	const HERE = dirname(fileURLToPath(import.meta.url));
36	const REPO_ROOT = join(HERE, "..");
37	
38	// ───────────────────────────────────────────────────────────────────────────
39	// Pinned constants (spec-gate-pinned; every element load-bearing)
40	// ───────────────────────────────────────────────────────────────────────────
41	
42	// Probe 1's subject commit -- parent of the env-merge fix 3cf6084.
43	export const PROBE1_COMMIT = "9027136";
44	
45	// KNOWN-BLOCKER list, pinned verbatim: the rubric the orchestrator's HUMAN
46	// JUDGMENT step checks probe-1 verdicts against. Never shown to the reviewer.
47	export const KNOWN_BLOCKERS = Object.freeze([
48	  "env merge semantics unstated: kimiLaneEnv() returns exactly two keys, and prose instructing spawn straight from the descriptor env replaces the child environment wholesale, losing HOME/PATH"
49	]);
50	
51	// Probe 2's subject: a small synthetic Crew Manifest whose outcome carries the
52	// misattribution the spec gate is expected to catch.
53	export const PROBE2_MANIFEST = Object.freeze({
54	  schema: "muster-crew-manifest/v1",
55	  item: "synthetic-reviewer-tier-probe",
56	  outcome: "Dispatch muster-reviewer as a headless kimi -p --agent-file leg: the stamped model_preference on the --agent-file agent engages the -p process's own model lanes, so the dispatch needs no -m flag.",
57	  crew: [
58	    { role: "reviewer", agent: "muster-reviewer", dispatch: "kimi -p --agent-file muster-reviewer.md" }
59	  ],
