97	// Briefs ride argv as the -p prompt, capped at KIMI_PROCESS_MAX_BRIEF
98	// (src/kimi-dispatch.js). The full `git show` output can exceed that budget;
99	// when it does, cut the artifact at the last newline that fits and say so in
100	// the brief -- deterministic, and the truncation is disclosed to the reviewer.
101	export function fitBrief(prefix, artifact) {
102	  if (prefix.length + artifact.length <= KIMI_PROCESS_MAX_BRIEF) return prefix + artifact;
103	  const note = "\n[artifact truncated to fit the -p brief budget]\n";
104	  const room = KIMI_PROCESS_MAX_BRIEF - prefix.length - note.length;
105	  const cut = artifact.lastIndexOf("\n", room);
106	  return prefix + artifact.slice(0, cut > 0 ? cut : room) + note;
107	}
