116	// Build all probe x lane cells with their kimiProcessDispatch descriptors.
117	// Pure construction -- spawns nothing (this is what --dry-run prints).
118	export function buildCells({ repoRoot = REPO_ROOT, agentFile = AGENT_FILE } = {}) {
119	  const briefs = buildBriefs(repoRoot);
120	  const cells = [];
