139	// THE MERGE RULE from the pinned blocker: the descriptor's env is an OVERRIDE
140	// pair merged over the ambient env -- never passed as the whole env (a
141	// wholesale replacement loses HOME/PATH and the child breaks). Do not regress.
142	export function spawnEnv(descriptorEnv, baseEnv = process.env) {
143	  return { ...baseEnv, ...descriptorEnv };
144	}
