146	// Retry trigger: nonzero exit, or truncated stdout (empty, or missing the
147	// session.resume_hint a complete stream-json run always ends with).
148	export function cellNeedsRetry({ exitCode, stdout }) {
149	  if (exitCode !== 0) return true;
150	  if (typeof stdout !== "string" || !stdout.trim()) return true;
151	  return captureSessionId(stdout) === null;
152	}
