154	// The raw verdict text, verbatim: the concatenated assistant messages from the
155	// stream-json stdout (first line is the verdict, per the brief's return
156	// contract). Falls back to the whole raw stdout when nothing parses -- the
157	// human-judgment step still gets exactly what the run emitted.
158	export function extractVerdictText(stdout) {
159	  if (typeof stdout !== "string") return "";
160	  const parts = [];
161	  for (const line of stdout.split("\n")) {
162	    if (!line.trim()) continue;
163	    let obj;
164	    try { obj = JSON.parse(line); } catch { continue; }
165	    if (obj?.role === "assistant" && typeof obj.content === "string" && obj.content.trim()) {
166	      parts.push(obj.content);
167	    }
168	  }
169	  return parts.length ? parts.join("\n") : stdout;
170	}
