172	// One spawn attempt: the descriptor's argv with the env merge rule, stdout
173	// captured to the results dir. Never throws on a nonzero exit -- the exit code
174	// is data (the retry policy and the results file both need it).
175	async function spawnAttempt(cell, { resultsDir, attempt }) {
176	  const { descriptor } = cell;
177	  const stdoutFile = join(resultsDir, `${cell.probe}.${cell.lane}.attempt-${attempt}.stdout.jsonl`);
178	  let exitCode = 0;
179	  let stdout = "";
180	  try {
181	    ({ stdout } = await pexecFile("kimi", descriptor.argv, {
182	      cwd: descriptor.cwd,
183	      env: spawnEnv(descriptor.env),
184	      timeout: 600_000,
185	      maxBuffer: 64 * 1024 * 1024
186	    }));
187	  } catch (err) {
188	    exitCode = typeof err.code === "number" ? err.code : 1;
189	    stdout = err.stdout ?? "";
190	  }
191	  await writeFile(stdoutFile, stdout, "utf8");
192	  return { exitCode, stdout, stdoutFile };
193	}
194	
195	// Run one cell: spawn, retry ONCE on nonzero exit/truncated output, then
196	// attribute tokens via captureSessionId -> resolveSessionForCwd ->
197	// readSessionUsage. Retried cells are marked so their token totals are
198	// EXCLUDED from the cost comparison (quality is still recorded).
199	export async function runCell(cell, { resultsDir }) {
200	  await mkdir(resultsDir, { recursive: true });
201	  let attempt = await spawnAttempt(cell, { resultsDir, attempt: 1 });
202	  let retried = false;
203	  if (cellNeedsRetry(attempt)) {
204	    retried = true;
205	    attempt = await spawnAttempt(cell, { resultsDir, attempt: 2 });
206	  }
207	  const sessionId = captureSessionId(attempt.stdout);
208	  let tokens = null;
209	  let tokensNote = null;
210	  if (sessionId) {
211	    try {
212	      const resolution = await resolveSessionForCwd({ cwd: cell.descriptor.cwd, capturedSessionId: sessionId });
213	      if (resolution.resolved) {
214	        tokens = (await readSessionUsage(resolution.sessionDir)).total;
215	      } else {
216	        tokensNote = `session unresolved: ${resolution.reason}`;
217	      }
218	    } catch (err) {
219	      tokensNote = `session attribution failed: ${err.message}`;
220	    }
221	  } else {
222	    tokensNote = "no session.resume_hint in stdout";
223	  }
224	  return {
225	    probe: cell.probe,
226	    gate: cell.gate,
227	    lane: cell.lane,
228	    exitCode: attempt.exitCode,
229	    verdictText: extractVerdictText(attempt.stdout),
230	    sessionId,
231	    tokens,
232	    ...(tokensNote ? { tokensNote } : {}),
233	    retried,
234	    attempts: retried ? 2 : 1,
235	    stdoutFile: attempt.stdoutFile
236	  };
237	}
