243	// Cost comparison per lane. RETRIED CELLS ARE EXCLUDED from the token sums --
244	// a retried cell paid for two runs, so folding it in would compare unequal
245	// work. Their verdicts still count for quality (they sit in cells[] verbatim).
246	export function buildCostComparison(cells) {
247	  const byLane = {};
248	  for (const lane of LANES) {
249	    const counted = cells.filter(c => c.lane === lane && !c.retried && c.tokens);
250	    const excluded = cells.filter(c => c.lane === lane && (c.retried || !c.tokens));
251	    const sum = { input: 0, output: 0, total: 0 };
252	    for (const c of counted) {
253	      sum.input += c.tokens.input;
254	      sum.output += c.tokens.output;
255	      sum.total += c.tokens.total;
256	    }
257	    byLane[lane] = {
258	      cellsCounted: counted.map(c => c.probe),
259	      cellsExcluded: excluded.map(c => `${c.probe} (${c.retried ? "retried" : "no tokens"})`),
260	      tokens: sum
261	    };
262	  }
263	  return {
264	    rule: "retried cells (and cells without token attribution) are EXCLUDED from per-lane token sums; their verdicts remain in cells[] for the quality judgment",
265	    byLane
266	  };
267	}
