272	    generatedAt: new Date().toISOString(),
273	    caveat: CAVEAT,
274	    rubric: {
275	      scoring: "human-judgment",
276	      note: "caught/missed is HUMAN JUDGMENT applied by the orchestrator against each cell's verbatim verdictText -- this harness deliberately does NOT keyword-score.",
277	      knownBlockers: [...KNOWN_BLOCKERS],
278	      expected: {
279	        "review-gate-diff": "FAIL with a BLOCKER finding matching the pinned known-blocker list",
280	        "spec-gate-manifest": "FAIL with a finding naming the misattribution: model_preference applies only to spawned subagents; the -p main agent's model comes only from -m"
281	      }
282	    },
283	    constants: {
284	      probe1Commit: PROBE1_COMMIT,
285	      probe2Manifest: PROBE2_MANIFEST,
286	      agentFile: AGENT_FILE,
287	      lanes: [...LANES]
288	    },
289	    cells,
290	    costComparison: buildCostComparison(cells),
291	    ...(outFile ? { outFile } : {})
292	  };
293	}
